        render_type = "rgb"

    total_loss = 0.0

    if do_guidance:
        out = self.training_substep(batch, batch_idx, guidance="guidance", render_type=render_type)
        total_loss += out["loss"]

    if do_ref:
        out = self.training_substep(batch, batch_idx, guidance="ref", render_type=render_type)
